        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ILightGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SnapTemplate, out var SnapTemplateInfo))
            {
                yield return SnapTemplateInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Properties is {} PropertiesItem)
            {
                foreach (var item in PropertiesItem.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.ValueCurrency, out var ValueCurrencyInfo))
            {
                yield return ValueCurrencyInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LensFlare, out var LensFlareInfo))
            {
                yield return LensFlareInfo;
            }
            if (FormLinkInformation.TryFactory(obj.GodRays, out var GodRaysInfo))
            {
                yield return GodRaysInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Sound, out var SoundInfo))
            {
                yield return SoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.HGLB, out var HGLBInfo))
            {
                yield return HGLBInfo;
            }
            yield break;
        }
        
